command:
cat > tetris.html << 'EOF'
<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>테트리스</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            font-family: Arial, sans-serif;
        }

        .container {
            display: flex;
            gap: 30px;
            padding: 20px;
        }

        .game-section {
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        h1 {
            color: white;
            text-align: center;
            font-size: 32px;
        }

        #gameBoard {
            display: grid;
            grid-template-columns: repeat(10, 40px);
            grid-template-rows: repeat(20, 40px);
            gap: 1px;
            background: #1a1a1a;
            padding: 5px;
            border: 3px solid white;
        }

        .block {
            background-color: #ccc;
            border: 1px solid #666;
        }

        .block.empty {
            background-color: #1a1a1a;
            border: 1px solid #333;
        }

        .block.active {
            background-color: #00ff00;
            border: 1px solid #00cc00;
        }

        .info-panel {
            background: rgba(255, 255, 255, 0.1);
            padding: 20px;
            border-radius: 10px;
            color: white;
            min-width: 150px;
        }

        .info-panel h2 {
            font-size: 18px;
            margin-bottom: 15px;
            border-bottom: 2px solid white;
            padding-bottom: 10px;
        }

        .info-item {
            margin-bottom: 20px;
        }

        .info-label {
            font-size: 12px;
            opacity: 0.8;
            margin-bottom: 5px;
        }

        .info-value {
            font-size: 24px;
            font-weight: bold;
        }

        #nextPiece {
            display: grid;
            grid-template-columns: repeat(4, 30px);
            grid-template-rows: repeat(4, 30px);
            gap: 2px;
            background: #1a1a1a;
            padding: 5px;
            margin-top: 10px;
        }

        #nextPiece .block {
            width: 30px;
            height: 30px;
        }

        .controls {
            background: rgba(255, 255, 255, 0.1);
            padding: 20px;
            border-radius: 10px;
            color: white;
            text-align: center;
        }

        .controls p {
            margin-bottom: 10px;
            font-size: 14px;
        }

        button {
            padding: 10px 20px;
            margin-top: 10px;
            background: #00ff00;
            border: none;
            border-radius: 5px;
            font-size: 16px;
            font-weight: bold;
            cursor: pointer;
            color: #1a1a1a;
            transition: background 0.3s;
        }

        button:hover {
            background: #00cc00;
        }

        button:active {
            transform: scale(0.95);
        }

        .game-over {
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            background: rgba(0, 0, 0, 0.9);
            padding: 40px;
            border-radius: 15px;
            text-align: center;
            color: white;
            z-index: 1000;
            display: none;
        }

        .game-over h2 {
            font-size: 36px;
            margin-bottom: 20px;
            color: #ff6b6b;
        }

        .game-over p {
            font-size: 20px;
            margin-bottom: 10px;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="game-section">
            <h1>테트리스</h1>
            <div id="gameBoard"></div>
            <div class="controls">
                <p>⬅️ ➡️: 좌우 이동</p>
                <p>⬇️: 빠른 낙하</p>
                <p>W: 회전</p>
                <button onclick="togglePause()">일시정지</button>
                <button onclick="resetGame()">새 게임</button>
            </div>
        </div>

        <div class="info-panel">
            <h2>정보</h2>
            <div class="info-item">
                <div class="info-label">점수</div>
                <div class="info-value" id="score">0</div>
            </div>
            <div class="info-item">
                <div class="info-label">완성된 줄</div>
                <div class="info-value" id="lines">0</div>
            </div>
            <div class="info-item">
                <div class="info-label">레벨</div>
                <div class="info-value" id="level">1</div>
            </div>
            <div class="info-item">
                <div class="info-label">다음 조각</div>
                <div id="nextPiece"></div>
            </div>
        </div>
    </div>

    <div class="game-over" id="gameOverScreen">
        <h2>게임 오버!</h2>
        <p id="finalScore">최종 점수: 0</p>
        <button onclick="resetGame()">다시 시작</button>
    </div>

    <script>
        const BOARD_WIDTH = 10;
        const BOARD_HEIGHT = 20;
        const COLORS = ['#FF6B6B', '#4ECDC4', '#45B7D1', '#FFA07A', '#98D8C8', '#F7DC6F', '#BB8FCE'];

        const TETROMINOS = [
            { shape: [[1, 1, 1, 1]], color: '#FF6B6B' },
            { shape: [[1, 1], [1, 1]], color: '#4ECDC4' },
            { shape: [[1, 1, 0], [0, 1, 1]], color: '#45B7D1' },
            { shape: [[0, 1, 1], [1, 1, 0]], color: '#FFA07A' },
            { shape: [[1, 0, 0], [1, 1, 1]], color: '#98D8C8' },
            { shape: [[0, 0, 1], [1, 1, 1]], color: '#F7DC6F' },
            { shape: [[0, 1, 0], [1, 1, 1]], color: '#BB8FCE' }
        ];

        let board = Array(BOARD_HEIGHT).fill(null).map(() => Array(BOARD_WIDTH).fill(0));
        let currentPiece = null;
        let nextPiece = null;
        let score = 0;
        let lines = 0;
        let level = 1;
        let gameOver = false;
        let paused = false;
        let gameSpeed = 800;

        function getRandomPiece() {
            const tetromino = TETROMINOS[Math.floor(Math.random() * TETROMINOS.length)];
            return {
                shape: tetromino.shape,
                color: tetromino.color,
                x: Math.floor(BOARD_WIDTH / 2) - Math.floor(tetromino.shape[0].length / 2),
                y: 0
            };
        }

        function init() {
            board = Array(BOARD_HEIGHT).fill(null).map(() => Array(BOARD_WIDTH).fill(0));
            currentPiece = getRandomPiece();
            nextPiece = getRandomPiece();
            score = 0;
            lines = 0;
            level = 1;
            gameOver = false;
            gameSpeed = 800;
            updateUI();
            render();
            startGameLoop();
        }

        function canMove(piece, newX, newY) {
            for (let y = 0; y < piece.shape.length; y++) {
                for (let x = 0; x < piece.shape[y].length; x++) {
                    if (piece.shape[y][x]) {
                        const boardX = newX + x;
                        const boardY = newY + y;
                        if (boardX < 0 || boardX >= BOARD_WIDTH || boardY >= BOARD_HEIGHT) return false;
                        if (boardY >= 0 && board[boardY][boardX]) return false;
                    }
                }
            }
            return true;
        }

        function rotatePiece(piece) {
            const rotated = {
                shape: piece.shape[0].map((_, i) => 
                    piece.shape.map(row => row[i]).reverse()
                ),
                color: piece.color,
                x: piece.x,
                y: piece.y
            };
            return canMove(rotated, rotated.x, rotated.y) ? rotated : piece;
        }

        function lockPiece() {
            for (let y = 0; y < currentPiece.shape.length; y++) {
                for (let x = 0; x < currentPiece.shape[y].length; x++) {
                    if (currentPiece.shape[y][x]) {
                        const boardY = currentPiece.y + y;
                        const boardX = currentPiece.x + x;
                        if (boardY >= 0 && boardY < BOARD_HEIGHT && boardX >= 0 && boardX < BOARD_WIDTH) {
                            board[boardY][boardX] = currentPiece.color;
                        }
                    }
                }
            }
            clearLines();
            currentPiece = nextPiece;
            nextPiece = getRandomPiece();

            if (!canMove(currentPiece, currentPiece.x, currentPiece.y)) {
                endGame();
            }
            updateUI();
        }

        function clearLines() {
            let clearedLines = 0;
            for (let y = BOARD_HEIGHT - 1; y >= 0; y--) {
                if (board[y].every(cell => cell)) {
                    board.splice(y, 1);
                    board.unshift(Array(BOARD_WIDTH).fill(0));
                    clearedLines++;
                    y++;
                }
            }
            if (clearedLines > 0) {
                score += [100, 300, 500, 800][clearedLines - 1] || 800;
                lines += clearedLines;
                level = Math.floor(lines / 10) + 1;
                gameSpeed = Math.max(200, 800 - (level - 1) * 50);
            }
        }

        function moveDown() {
            if (canMove(currentPiece, currentPiece.x, currentPiece.y + 1)) {
                currentPiece.y++;
            } else {
                lockPiece();
            }
            render();
        }

        function moveLeft() {
            if (canMove(currentPiece, currentPiece.x - 1, currentPiece.y)) {
                currentPiece.x--;
                render();
            }
        }

        function moveRight() {
            if (canMove(currentPiece, currentPiece.x + 1, currentPiece.y)) {
                currentPiece.x++;
                render();
            }
        }

        function rotate() {
            currentPiece = rotatePiece(currentPiece);
            render();
        }

        function render() {
            const gameBoard = document.getElementById('gameBoard');
            gameBoard.innerHTML = '';

            for (let y = 0; y < BOARD_HEIGHT; y++) {
                for (let x = 0; x < BOARD_WIDTH; x++) {
                    const block = document.createElement('div');
                    block.className = 'block';
                    if (board[y][x]) {
                        block.style.backgroundColor = board[y][x];
                    } else {
                        block.className += ' empty';
                    }
                    gameBoard.appendChild(block);
                }
            }

            for (let y = 0; y < currentPiece.shape.length; y++) {
                for (let x = 0; x < currentPiece.shape[y].length; x++) {
                    if (currentPiece.shape[y][x]) {
                        const boardY = currentPiece.y + y;
                        const boardX = currentPiece.x + x;
                        if (boardY >= 0 && boardY < BOARD_HEIGHT && boardX >= 0 && boardX < BOARD_WIDTH) {
                            const index = boardY * BOARD_WIDTH + boardX;
                            gameBoard.children[index].style.backgroundColor = currentPiece.color;
                        }
                    }
                }
            }

            renderNextPiece();
        }

        function renderNextPiece() {
            const nextPieceDiv = document.getElementById('nextPiece');
            nextPieceDiv.innerHTML = '';

            for (let y = 0; y < 4; y++) {
                for (let x = 0; x < 4; x++) {
                    const block = document.createElement('div');
                    block.className = 'block empty';

                    if (y < nextPiece.shape.length && x < nextPiece.shape[y].length && nextPiece.shape[y][x]) {
                        block.style.backgroundColor = nextPiece.color;
                        block.className = 'block';
                    }
                    nextPieceDiv.appendChild(block);
                }
            }
        }

        function updateUI() {
            document.getElementById('score').textContent = score;
            document.getElementById('lines').textContent = lines;
            document.getElementById('level').textContent = level;
        }

        function endGame() {
            gameOver = true;
            document.getElementById('finalScore').textContent = `최종 점수: ${score}`;
            document.getElementById('gameOverScreen').style.display = 'block';
        }

        function togglePause() {
            paused = !paused;
        }

        function resetGame() {
            document.getElementById('gameOverScreen').style.display = 'none';
            init();
        }

        let gameLoopId = null;

        function startGameLoop() {
            if (gameLoopId) clearInterval(gameLoopId);
            gameLoopId = setInterval(() => {
                if (!gameOver && !paused) {
                    moveDown();
                }
            }, gameSpeed);
        }

        document.addEventListener('keydown', (e) => {
            if (gameOver || paused) return;

            switch(e.key) {
                case 'ArrowLeft':
                    moveLeft();
                    e.preventDefault();
                    break;
                case 'ArrowRight':
                    moveRight();
                    e.preventDefault();
                    break;
                case 'ArrowDown':
                    moveDown();
                    e.preventDefault();
                    break;
                case 'w':
                case 'W':
                    rotate();
                    e.preventDefault();
                    break;
            }
        });

        init();
    </script>
</body>
</html>
EOF

