echo '<!DOCTYPE html>
<html lang="ko">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>테트리스</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body { display: flex; justify-content: center; align-items: center; min-height: 100vh; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); font-family: Arial, sans-serif; }
        .container { display: flex; gap: 30px; align-items: flex-start; padding: 20px; }
        .game-board { display: grid; grid-template-columns: repeat(10, 30px); grid-gap: 1px; background: #111; padding: 5px; box-shadow: 0 0 20px rgba(0, 0, 0, 0.5); }
        .cell { width: 30px; height: 30px; background: #222; border: 1px solid #333; }
        .cell.filled { background: currentColor; box-shadow: inset 0 0 2px rgba(0, 0, 0, 0.5); }
        .sidebar { background: rgba(255, 255, 255, 0.95); padding: 20px; border-radius: 10px; box-shadow: 0 0 20px rgba(0, 0, 0, 0.3); min-width: 200px; }
        .sidebar h1 { color: #667eea; margin-bottom: 20px; font-size: 28px; }
        .info { margin-bottom: 20px; }
        .info label { display: block; color: #333; font-weight: bold; margin-bottom: 5px; }
        .info value { display: block; font-size: 24px; color: #667eea; font-weight: bold; }
        .next-piece { margin-bottom: 20px; padding: 10px; background: #f0f0f0; border-radius: 5px; }
        .next-piece h3 { color: #333; margin-bottom: 10px; font-size: 14px; }
        .next-grid { display: grid; grid-template-columns: repeat(4, 20px); grid-gap: 1px; background: #ddd; padding: 3px; }
        .next-grid .cell { width: 20px; height: 20px; }
        .buttons { display: flex; flex-direction: column; gap: 10px; margin-bottom: 20px; }
        button { padding: 12px 20px; font-size: 16px; font-weight: bold; border: none; border-radius: 5px; cursor: pointer; transition: all 0.3s; }
        #startBtn { background: #4CAF50; color: white; }
        #startBtn:hover { background: #45a049; transform: scale(1.05); }
        #pauseBtn { background: #2196F3; color: white; }
        #pauseBtn:hover { background: #0b7dda; transform: scale(1.05); }
        .controls { background: #f0f0f0; padding: 15px; border-radius: 5px; margin-bottom: 20px; }
        .controls h3 { color: #333; margin-bottom: 10px; font-size: 14px; }
        .controls p { color: #666; font-size: 12px; margin: 5px 0; }
        .game-over { display: none; position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); background: rgba(0, 0, 0, 0.9); color: white; padding: 40px; border-radius: 10px; text-align: center; z-index: 1000; min-width: 300px; }
        .game-over h2 { font-size: 36px; margin-bottom: 20px; }
        .game-over p { font-size: 20px; margin-bottom: 10px; }
        .game-over button { background: #667eea; color: white; margin-top: 20px; }
        .game-over button:hover { background: #764ba2; }
    </style>
</head>
<body>
    <div class="container">
        <div class="game-board" id="gameBoard"></div>
        <div class="sidebar">
            <h1>TETRIS</h1>
            <div class="buttons">
                <button id="startBtn">게임 시작</button>
                <button id="pauseBtn">일시정지</button>
            </div>
            <div class="info">
                <label>점수</label>
                <value id="score">0</value>
            </div>
            <div class="info">
                <label>레벨</label>
                <value id="level">1</value>
            </div>
            <div class="info">
                <label>제거된 줄</label>
                <value id="lines">0</value>
            </div>
            <div class="next-piece">
                <h3>다음 블록</h3>
                <div class="next-grid" id="nextGrid"></div>
            </div>
            <div class="controls">
                <h3>조작</h3>
                <p>← → : 좌우 이동</p>
                <p>↓ : 빠른 하강</p>
                <p>Z : 회전</p>
                <p>스페이스 : 즉시 하강</p>
            </div>
        </div>
    </div>
    <div class="game-over" id="gameOverScreen">
        <h2>게임 오버!</h2>
        <p id="finalScore"></p>
        <button onclick="location.reload()">다시 시작</button>
    </div>
    <script>
        const ROWS = 20, COLS = 10;
        const TETROMINOES = [
            { shape: [[1,1,1,1]], color: "#FF6B6B" },
            { shape: [[1,1],[1,1]], color: "#4ECDC4" },
            { shape: [[0,1,1],[1,1,0]], color: "#FFE66D" },
            { shape: [[1,1,0],[0,1,1]], color: "#95E1D3" },
            { shape: [[1,0,0],[1,1,1]], color: "#C7CEEA" },
            { shape: [[0,0,1],[1,1,1]], color: "#FF9999" },
            { shape: [[0,1,0],[1,1,1]], color: "#A8D8EA" }
        ];
        let board = Array(ROWS).fill(null).map(() => Array(COLS).fill(null));
        let currentPiece = null, nextPiece = null, score = 0, lines = 0, level = 1;
        let gameRunning = false, gamePaused = false, dropInterval = null;

        function initGame() {
            board = Array(ROWS).fill(null).map(() => Array(COLS).fill(null));
            score = lines = 0; level = 1; gameRunning = true; gamePaused = false;
            currentPiece = getRandomPiece(); nextPiece = getRandomPiece(); updateUI(); startDrop();
        }

        function getRandomPiece() {
            const t = TETROMINOES[Math.floor(Math.random() * TETROMINOES.length)];
            return { shape: t.shape, color: t.color, x: Math.floor(COLS / 2) - Math.floor(t.shape[0].length / 2), y: 0 };
        }

        function drawBoard() {
            const gb = document.getElementById("gameBoard");
            gb.innerHTML = "";
            for (let r = 0; r < ROWS; r++) {
                for (let c = 0; c < COLS; c++) {
                    const cell = document.createElement("div");
                    cell.className = "cell";
                    if (board[r][c]) { cell.classList.add("filled"); cell.style.color = board[r][c]; }
                    gb.appendChild(cell);
                }
            }
            if (currentPiece) {
                currentPiece.shape.forEach((row, y) => {
                    row.forEach((val, x) => {
                        if (val) {
                            const r = currentPiece.y + y, c = currentPiece.x + x;
                            if (r >= 0 && r < ROWS && c >= 0 && c < COLS) {
                                const idx = r * COLS + c;
                                if (!board[r][c]) { gb.children[idx].classList.add("filled"); gb.children[idx].style.color = currentPiece.color; }
                            }
                        }
                    });
                });
            }
        }

        function drawNextPiece() {
            const ng = document.getElementById("nextGrid");
            ng.innerHTML = "";
            for (let i = 0; i < 16; i++) {
                const cell = document.createElement("div");
                cell.className = "cell";
                ng.appendChild(cell);
            }
            if (nextPiece) {
                nextPiece.shape.forEach((row, y) => {
                    row.forEach((val, x) => {
                        if (val) {
                            const idx = y * 4 + x;
                            ng.children[idx].classList.add("filled");
                            ng.children[idx].style.color = nextPiece.color;
                        }
                    });
                });
            }
        }

        function canMove(piece, newX, newY) {
            for (let y = 0; y < piece.shape.length; y++) {
                for (let x = 0; x < piece.shape[y].length; x++) {
                    if (piece.shape[y][x]) {
                        const bX = newX + x, bY = newY + y;
                        if (bX < 0 || bX >= COLS || bY >= ROWS) return false;
                        if (bY >= 0 && board[bY][bX]) return false;
                    }
                }
            }
            return true;
        }

        function lockPiece() {
            currentPiece.shape.forEach((row, y) => {
                row.forEach((val, x) => {
                    if (val) {
                        const r = currentPiece.y + y, c = currentPiece.x + x;
                        if (r >= 0 && r < ROWS && c >= 0 && c < COLS) board[r][c] = currentPiece.color;
                    }
                });
            });
            checkLines(); currentPiece = nextPiece; nextPiece = getRandomPiece();
            if (!canMove(currentPiece, currentPiece.x, currentPiece.y)) endGame();
        }

        function checkLines() {
            let completed = 0;
            for (let r = ROWS - 1; r >= 0; r--) {
                if (board[r].every(c => c !== null)) {
                    board.splice(r, 1);
                    board.unshift(Array(COLS).fill(null));
                    completed++; r++;
                }
            }
            if (completed > 0) {
                lines += completed; score += completed * 100 * level; level = Math.floor(lines / 10) + 1; updateUI();
            }
        }

        function rotatePiece() {
            const rotated = currentPiece.shape[0].map((_, colIndex) => currentPiece.shape.map(row => row[colIndex]).reverse());
            const oldShape = currentPiece.shape;
            currentPiece.shape = rotated;
            if (!canMove(currentPiece, currentPiece.x, currentPiece.y)) currentPiece.shape = oldShape;
        }

        function movePiece(dx, dy) {
            if (canMove(currentPiece, currentPiece.x + dx, currentPiece.y + dy)) {
                currentPiece.x += dx; currentPiece.y += dy; return true;
            }
            return false;
        }

        function drop() {
            if (!gameRunning || gamePaused) return;
            if (!movePiece(0, 1)) lockPiece();
            drawBoard();
        }

        function startDrop() {
            dropInterval = setInterval(drop, Math.max(100, 500 - level * 50));
        }

        function updateUI() {
            document.getElementById("score").textContent = score;
            document.getElementById("level").textContent = level;
            document.getElementById("lines").textContent = lines;
            drawBoard(); drawNextPiece();
        }

        function endGame() {
            gameRunning = false; clearInterval(dropInterval);
            document.getElementById("finalScore").textContent = `최종 점수: ${score}`;
            document.getElementById("gameOverScreen").style.display = "block";
        }

        document.getElementById("startBtn").addEventListener("click", () => {
            if (!gameRunning) { initGame(); document.getElementById("startBtn").textContent = "다시 시작"; }
        });

        document.getElementById("pauseBtn").addEventListener("click", () => {
            if (gameRunning) {
                gamePaused = !gamePaused;
                document.getElementById("pauseBtn").textContent = gamePaused ? "재개" : "일시정지";
            }
        });

        document.addEventListener("keydown", (e) => {
            if (!gameRunning || gamePaused) return;
            switch(e.key) {
                case "ArrowLeft": movePiece(-1, 0); break;
                case "ArrowRight": movePiece(1, 0); break;
                case "ArrowDown": drop(); break;
                case "z":
                case "Z": rotatePiece(); break;
                case " ": e.preventDefault(); while (movePiece(0, 1)); lockPiece(); break;
            }
            drawBoard();
        });

        drawBoard(); drawNextPiece();
    </script>
</body>
</html>' > tetris.html && cat tetris.html | head -5

