<body>
    <div class="container">
        <div class="game-board" id="gameBoard"></div>

        <div class="sidebar">
            <h1>TETRIS</h1>

            <div class="buttons">
                <button id="startBtn">게임 시작</button>
                <button id="pauseBtn">일시정지</button>
            </div>

            <div class="info">
                <label>점수</label>
                <value id="score">0</value>
            </div>

            <div class="info">
                <label>레벨</label>
                <value id="level">1</value>
            </div>

            <div class="info">
                <label>제거된 줄</label>
                <value id="lines">0</value>
            </div>

            <div class="next-piece">
                <h3>다음 블록</h3>
                <div class="next-grid" id="nextGrid"></div>
            </div>

            <div class="controls">
                <h3>조작</h3>
                <p>← → : 좌우 이동</p>
                <p>↓ : 빠른 하강</p>
                <p>Z : 회전</p>
                <p>스페이스 : 즉시 하강</p>
            </div>
        </div>
    </div>

    <div class="game-over" id="gameOverScreen">
        <h2>게임 오버!</h2>
        <p id="finalScore"></p>
        <button onclick="location.reload()">다시 시작</button>
    </div>

    <script>
        const ROWS = 20;
        const COLS = 10;
        const CELL_SIZE = 30;

        const TETROMINOES = [
            { shape: [[1,1,1,1]], color: '#FF6B6B' }, // I
            { shape: [[1,1],[1,1]], color: '#4ECDC4' }, // O
            { shape: [[0,1,1],[1,1,0]], color: '#FFE66D' }, // S
            { shape: [[1,1,0],[0,1,1]], color: '#95E1D3' }, // Z
            { shape: [[1,0,0],[1,1,1]], color: '#C7CEEA' }, // J
            { shape: [[0,0,1],[1,1,1]], color: '#FF9999' }, // L
            { shape: [[0,1,0],[1,1,1]], color: '#A8D8EA' } // T
        ];

        let board = Array(ROWS).fill(null).map(() => Array(COLS).fill(null));
        let currentPiece = null;
        let nextPiece = null;
        let score = 0;
        let lines = 0;
        let level = 1;
        let gameRunning = false;
        let gamePaused = false;
        let dropInterval = null;

        function initGame() {
            board = Array(ROWS).fill(null).map(() => Array(COLS).fill(null));
            score = 0;
            lines = 0;
            level = 1;
            gameRunning = true;
            gamePaused = false;
            currentPiece = getRandomPiece();
            nextPiece = getRandomPiece();
            updateUI();
            startDrop();
        }

        function getRandomPiece() {
            const tetromino = TETROMINOES[Math.floor(Math.random() * TETROMINOES.length)];
            return {
                shape: tetromino.shape,
                color: tetromino.color,
                x: Math.floor(COLS / 2) - Math.floor(tetromino.shape[0].length / 2),
                y: 0
            };
        }

        function drawBoard() {
            const gameBoard = document.getElementById('gameBoard');
            gameBoard.innerHTML = '';

            for (let r = 0; r < ROWS; r++) {
                for (let c = 0; c < COLS; c++) {
                    const cell = document.createElement('div');
                    cell.className = 'cell';
                    if (board[r][c]) {
                        cell.classList.add('filled');
                        cell.style.color = board[r][c];
                    }
                    gameBoard.appendChild(cell);
                }
            }

            // Draw current piece
            if (currentPiece) {
                currentPiece.shape.forEach((row, y) => {
                    row.forEach((val, x) => {
                        if (val) {
                            const r = currentPiece.y + y;
                            const c = currentPiece.x + x;
                            if (r >= 0 && r < ROWS && c >= 0 && c < COLS) {
                                const idx = r * COLS + c;
                                if (!board[r][c]) {
                                    gameBoard.children[idx].classList.add('filled');
                                    gameBoard.children[idx].style.color = currentPiece.color;
                                }
                            }
                        }
                    });
                });
            }
        }

        function drawNextPiece() {
            const nextGrid = document.getElementById('nextGrid');
            nextGrid.innerHTML = '';

            for (let i = 0; i < 16; i++) {
                const cell = document.createElement('div');
                cell.className = 'cell';
                nextGrid.appendChild(cell);
            }

            if (nextPiece) {
                nextPiece.shape.forEach((row, y) => {
                    row.forEach((val, x) => {
                        if (val) {
                            const idx = y * 4 + x;
                            nextGrid.children[idx].classList.add('filled');
                            nextGrid.children[idx].style.color = nextPiece.color;
                        }
                    });
                });
            }
        }

        function canMove(piece, newX, newY) {
            for (let y = 0; y < piece.shape.length; y++) {
                for (let x = 0; x < piece.shape[y].length; x++) {
                    if (piece.shape[y][x]) {
                        const boardX = newX + x;
                        const boardY = newY + y;

                        if (boardX < 0 || boardX >= COLS || boardY >= ROWS) {
                            return false;
                        }

                        if (boardY >= 0 && board[boardY][boardX]) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        function lockPiece() {
            currentPiece.shape.forEach((row, y) => {
                row.forEach((val, x) => {
                    if (val) {
                        const r = currentPiece.y + y;
                        const c = currentPiece.x + x;
                        if (r >= 0 && r < ROWS && c >= 0 && c < COLS) {
                            board[r][c] = currentPiece.color;
                        }
                    }
                });
            });

            checkLines();
            currentPiece = nextPiece;
            nextPiece = getRandomPiece();

            if (!canMove(currentPiece, currentPiece.x, currentPiece.y)) {
                endGame();
            }
        }

        function checkLines() {
            let completedLines = 0;
            for (let r = ROWS - 1; r >= 0; r--) {
                if (board[r].every(cell => cell !== null)) {
                    board.splice(r, 1);
                    board.unshift(Array(COLS).fill(null));
                    completedLines++;
                    r++;
                }
            }

            if (completedLines > 0) {
                lines += completedLines;
                score += completedLines * 100 * level;
                level = Math.floor(lines / 10) + 1;
                updateUI();
            }
        }

        function rotatePiece() {
            const rotated = currentPiece.shape[0].map((_, colIndex) => 
                currentPiece.shape.map(row => row[colIndex]).reverse()
            );

            const oldShape = currentPiece.shape;
            currentPiece.shape = rotated;

            if (!canMove(currentPiece, currentPiece.x, currentPiece.y)) {
                currentPiece.shape = oldShape;
            }
        }

        function movePiece(dx, dy) {
            if (canMove(currentPiece, currentPiece.x + dx, currentPiece.y + dy)) {
                currentPiece.x += dx;
                currentPiece.y += dy;
                return true;
            }
            return false;
        }

        function drop() {
            if (!gameRunning || gamePaused) return;

            if (!movePiece(0, 1)) {
                lockPiece();
            }
            drawBoard();
        }

        function startDrop() {
            dropInterval = setInterval(drop, Math.max(100, 500 - level * 50));
        }

        function updateUI() {
            document.getElementById('score').textContent = score;
            document.getElementById('level').textContent = level;
            document.getElementById('lines').textContent = lines;
            drawBoard();
            drawNextPiece();
        }

        function endGame() {
            gameRunning = false;
            clearInterval(dropInterval);
            document.getElementById('finalScore').textContent = `최종 점수: ${score}`;
            document.getElementById('gameOverScreen').style.display = 'block';
        }

        document.getElementById('startBtn').addEventListener('click', () => {
            if (!gameRunning) {
                initGame();
                document.getElementById('startBtn').textContent = '다시 시작';
            }
        });

        document.getElementById('pauseBtn').addEventListener('click', () => {
            if (gameRunning) {
                gamePaused = !gamePaused;
                document.getElementById('pauseBtn').textContent = gamePaused ? '재개' : '일시정지';
            }
        });

        document.addEventListener('keydown', (e) => {
            if (!gameRunning || gamePaused) return;

            switch(e.key) {
                case 'ArrowLeft':
                    movePiece(-1, 0);
                    break;
                case 'ArrowRight':
                    movePiece(1, 0);
                    break;
                case 'ArrowDown':
                    drop();
                    break;
                case 'z':
                case 'Z':
                    rotatePiece();
                    break;
                case ' ':
                    e.preventDefault();
                    while (movePiece(0, 1));
                    lockPiece();
                    break;
            }
            drawBoard();
        });

        drawBoard();
        drawNextPiece();
    </script>
</body>
</html>
