        .game-board {
            position: relative;
            width: 300px;
            height: 600px;
            background: #0f3460;
            border: 3px solid #e94560;
            display: grid;
            grid-template-columns: repeat(10, 1fr);
            grid-template-rows: repeat(20, 1fr);
            gap: 0;
        }

        .cell {
